#pragma once
#include <array>

// The fitted data of each piano: MeasuredModalData.h holds the grand's and
// MeasuredUprightData.h the upright's, both generated by
// Tools/fit_realtime_modal.py. A table over the recorded pitches is flat,
// one row per recorded pitch.
namespace keyra { namespace measured {
// The most velocity layers a piano is measured at; one measured at fewer
// leaves the rest of each per-layer array unused.
constexpr int maxLayers=12;
// One lane of a partial: decay rate (1/s), frequency offset from the
// partial (Hz), the pickup shape (left real; right complex; mean channel
// power 1), and per layer its level (dB) and its phase (rad) at string
// contact, the layers aligned to one pattern across the partials.
struct Lane { float rate, offsetHz, left, rightRe, rightIm; std::array<float,maxLayers> levelDb, phase; };
// A partial of the stiff-string series: its tuning (cents from the series),
// the rise 1 - e^(-t/rise) its lanes share (seconds at velocity 64; log
// slope per 64 velocity), and its lanes, fastest first.
struct Partial { int order; float cents, riseSeconds, riseSlope; std::array<Lane,4> lanes; };
// A component beside the series (below A3: the unison strings' own series
// at high orders and phantom partials): one lane at its place by the
// series (cents from an order), starting at contact.
struct Extra { int order; float cents; Lane lane; };
// A recorded pitch: its series (f1 at A4 = 440 Hz, stiffness B), per layer
// the shortest rise its partials take (seconds), measured from the
// recordings' onsets, and its partials and extra components.
struct Anchor { int note; float f1, B; std::array<float,maxLayers> onsetRise; int first, count, extraFirst, extraCount; };
// One of the strings from F6 up, which have no dampers: every strike sets
// them ringing, and they ring on after the key is let go. Its frequency
// (cents from the pitch the engine gives its key), decay rate (1/s) and
// stereo pickup (left real; right complex; mean channel power 1).
struct HaloString { float cents, rate, left, rightRe, rightIm; };
// A mode of the soundboard and case, which every strike knocks, measured
// under the treble's fundamentals: its frequency (Hz), decay rate (1/s) and
// one stereo pickup (left real; right complex; mean channel power 1).
struct BodyMode { float hz, rate, left, rightRe, rightIm; };
// How a recorded pitch's strike knocks a body mode: the level (dB at
// velocity 64), its slope (dB per 64 velocity) and the phase (rad) at
// string contact.
struct Knock { float levelDb, slopeDb, phase; };
// A knock of the action on a body mode: the level (dB) and phase (rad) at
// the knock's onset.
struct ActionKnock { float levelDb, phase; };
// What the felt leaves ringing of a damped partial at frequency f, with
// x = log2(f / 261.63 Hz): of its power when the felt lands, the share
// 10^((shareDb + shareSlopeDb x) / 10), at most all of it, falls at
// e^(logRate + logRateSlope x) (1/s at full contact) besides the partial's
// own decay, while the felt takes the rest at the engine's felt loss.
struct Damper { float shareDb, shareSlopeDb, logRate, logRateSlope; };
// A third-octave band of the board's dense ring above the modes: its centre
// (Hz) and its left/right coherence.
struct NoiseBand { float hz, coherence; };
// How a recorded pitch's strike excites a band: the decay rate (1/s), the
// right-over-left level difference (dB) and per layer the noise density at
// contact (dB re 1/Hz).
struct Noise { float rate, balanceDb; std::array<float,maxLayers> densityDb; };
}} // namespace keyra::measured
